// Versioned Core campaigns for two to four banks. Private plans remain in the
// engine's one owner draft; the roster, map and online lobby use public views.
const CORE_MULTI_COLORS=['#2878e0','#d74c62','#218a65','#9b61c7'];
let coreMultiUi={owner:null,cycle:null,campaign:null,tab:'month',market:null,branch:null,notice:'',error:'',revision:0};
let coreMultiSetup={count:4,map:'continental',scenario:'balanced',difficulty:'vp',seed:'',players:CORE_MULTI_COLORS.map((color,i)=>({name:i?'Bank '+(i+1):'Your Bank',isBot:i>0,color}))};
let coreMultiOnline={base:'',room:'',seat:null,token:'',lobby:null,busy:false,timer:null,generation:0,error:'',notice:'',connected:false};
let coreMultiLocalDrafts={campaign:null,cycle:null,plans:new Map()};
let coreMultiConnecting=false;
let coreMultiRemember=true;
const coreMultiCopy=value=>JSON.parse(JSON.stringify(value));
const coreMultiMoney=value=>Number.isFinite(value)?'$'+Math.round(value).toLocaleString('en-US'):'Unavailable';
const coreMultiColor=(color,i=0)=>/^#[0-9a-f]{6}$/i.test(String(color))?color:CORE_MULTI_COLORS[i%4];
function coreMultiplayerEnabled(v){return v?.coreMultiplayerVersion===1;}
function coreMultiplayerOnlineActive(){return !!(coreMultiOnline.token&&coreMultiOnline.room);}
function coreMultiBanks(v){return v.banks||[v.me,...(v.rivals||[v.rival])].filter(Boolean);}
function coreMultiBadge(bank,i=0){return '<span class="cm-bank-badge" style="--bank-color:'+coreMultiColor(bank.color,i)+'" aria-hidden="true">'+esc(String(bank.name||'Bank').trim().split(/\s+/).map(x=>x[0]).join('').slice(0,3).toUpperCase())+'</span>';}
function coreMultiplayerRestore(){
 $('#gameScreen')?.classList.remove('core-multiplayer-enabled');document.body?.classList.remove('core-multiplayer-active');
 if($('#coreMultiplayerGame'))$('#coreMultiplayerGame').hidden=true;
}
function coreMultiEnsureDraft(v){
 if(game&&(coreMultiLocalDrafts.campaign!==game||coreMultiLocalDrafts.cycle!==v.cycle))coreMultiLocalDrafts={campaign:game,cycle:v.cycle,plans:new Map()};
 if(!draft||draftOwner!==v.me.id||lastCycle!==v.cycle){draft=coreMultiCopy(v.me.submittedPlan||(game&&coreMultiLocalDrafts.plans.get(v.me.id))||E.defaultCoreMultiplayerPlan(v));draftOwner=v.me.id;lastCycle=v.cycle;}
 if(v.me.submitted&&v.me.submittedPlan)draft=coreMultiCopy(v.me.submittedPlan);
 const campaign=game||coreMultiOnline.token||view;
 if(coreMultiUi.owner!==v.me.id||coreMultiUi.cycle!==v.cycle||coreMultiUi.campaign!==campaign)coreMultiUi={owner:v.me.id,cycle:v.cycle,campaign,tab:'month',market:draft.focus,branch:Object.keys(v.strategyBranches||{})[0],notice:'',error:'',revision:coreMultiUi.revision+1};
}
function coreMultiToken(v=currentView()){return {frame:game||view,owner:v?.me?.id,cycle:v?.cycle,revision:coreMultiUi.revision,generation:coreMultiOnline.generation};}
function coreMultiCurrent(token,write=true){const v=currentView();return !!(token&&v&&coreMultiplayerEnabled(v)&&token.frame===(game||view)&&token.owner===v.me.id&&token.cycle===v.cycle&&token.revision===coreMultiUi.revision&&token.generation===coreMultiOnline.generation&&draftOwner===v.me.id&&lastCycle===v.cycle&&(!write||!v.me.submitted&&!v.me.eliminated&&!v.gameOver&&!coreMultiOnline.writing));}
function coreMultiSetShell(){show('#gameScreen');interfaceRestoreCore?.();$('#gameScreen').classList.add('core-multiplayer-enabled');document.body?.classList.add('core-multiplayer-active');$('#coreMultiplayerGame').hidden=false;}
function coreMultiReview(v,plan=draft){
 const errors=[],add=text=>{if(text&&!errors.includes(text))errors.push(text);};let budget=null,forecast=null;
 if(!v.territories[plan.focus]?.unlocked||v.territories[plan.focus]?.exited?.[0])add('Choose an open market your bank has not exited.');
 if(!['a','b'].includes(plan.decision))add('Answer the executive decision.');
 const allocations=Object.values(plan.allocation||{});if(allocations.some(n=>!Number.isSafeInteger(n)||n<0)||allocations.reduce((a,b)=>a+b,0)!==v.me.stats.staff)add('Allocate all '+v.me.stats.staff+' bankers in whole numbers.');
 for(const [branch,raw]of Object.entries(plan.investments||{})){const n=Number(raw);if(!v.strategyBranches[branch]||!Number.isSafeInteger(n)||n<0||n>v.capabilityCap||n>0&&n<1000)add('Research contributions must be whole dollars, zero or at least $1,000, within the monthly cap.');}
 for(const [branch,amount]of Object.entries(plan.investments||{})){const tiers=v.capabilityTiers[branch]||E.CAPABILITY_TIERS[branch];if(tiers&&Number(amount)>tiers.at(-1)-E.capabilitySpend(v.me,branch))add('Research funding exceeds the remaining cost of this capability.');}
 for(const [branch,model]of Object.entries(plan.specializations||{})){if(!model||v.me.specializations?.[branch]===model)continue;const tiers=v.capabilityTiers[branch]||E.CAPABILITY_TIERS[branch];if(!E.researchModelTable(v.me)[branch]?.[model]||!tiers||E.capabilitySpend(v.me,branch)+Number(plan.investments?.[branch]||0)<tiers[0])add('An operating model requires its capability’s first funded milestone.');}
 try{const status=E.projectPlanStatus(v.me,plan,v);if(!status.eligible)add(status.reason);budget=status.quote||E.planBudget(v.me,plan,v);if((budget.discretionaryRemaining??budget.remaining)<0)add('The plan exceeds available cash or capital. Reduce commitments.');}catch(error){add(error.message);}
 try{const status=E.competitiveActionStatus(v.me,plan.competitiveAction||'none');if(!status.eligible)add(status.reason);}catch(error){add(error.message);}
 if(plan.rivalId&&!coreMultiBanks(v).some(bank=>bank.id===plan.rivalId&&bank.id!==v.me.id&&!bank.eliminated))add('Choose an active opposing bank.');
 try{if(!errors.length)forecast=E.operatingPreview(v.me,plan,v.economy,v,true);}catch(error){add('Operating forecast unavailable: '+error.message);}
 return {errors,budget,forecast};
}
function coreMultiUpdate(token,edit){
 if(!coreMultiCurrent(token))return false;
 try{const next=coreMultiCopy(draft);edit(next,currentView());draft=next;if(game)coreMultiLocalDrafts.plans.set(draftOwner,coreMultiCopy(next));coreMultiUi.error='';coreMultiUi.notice='Monthly plan updated. Orders execute when all active human banks are ready.';renderCoreMultiplayer(currentView());return true;}
 catch(error){coreMultiUi.error=error.message;renderCoreMultiplayer(currentView());return false;}
}
function coreMultiStandings(v){
 const rows=[...coreMultiBanks(v)].sort((a,b)=>(b.score||0)-(a.score||0));
 return '<div class="cm-table-scroll" tabindex="0" aria-label="Bank standings"><table><caption>Public standings</caption><thead><tr><th scope="col">Bank</th><th scope="col">Score</th><th scope="col">Markets</th><th scope="col">Deposits</th><th scope="col">Capital</th><th scope="col">Status</th></tr></thead><tbody>'+rows.map((bank,i)=>'<tr'+(bank.id===v.me.id?' class="cm-own-bank"':'')+'><th scope="row">'+coreMultiBadge(bank,i)+esc(bank.name)+(bank.id===v.me.id?' · You':'')+'<small>'+ (bank.isBot?'AI':'Human')+'</small></th><td>'+Number(bank.score||0).toFixed(1)+'</td><td>'+esc(bank.controlled??0)+'</td><td>'+coreMultiMoney(bank.stats?.deposits)+'</td><td>'+ (Number.isFinite(bank.capitalRatio)?bank.capitalRatio.toFixed(1)+'%':'Unavailable')+'</td><td>'+ (bank.eliminated?'Eliminated':bank.submitted?'Ready':'Planning')+'</td></tr>').join('')+'</tbody></table></div>';
}
function coreMultiMonth(v,review){
 let quote='';try{if(draft.decision){const q=E.decisionQuote(v.me,v.event,draft.decision);quote='<p class="cm-note">Known response: cash change '+coreMultiMoney(q.cashChange)+' · capital / equity change '+coreMultiMoney(q.equityChange)+'. The operating forecast excludes uncertain rival actions.</p>';}}catch(error){quote='<p class="cm-error">'+esc(error.message)+'</p>';}
 return '<div class="cm-columns"><section class="cm-card"><h2>'+esc(v.event?.name||'Executive decision')+'</h2><p>'+esc(v.event?.text||'')+'</p><div class="cm-decision">'+['a','b'].map(key=>'<button type="button" class="cm-choice" data-cm-decision="'+key+'" aria-pressed="'+(draft.decision===key)+'"><b>'+esc(v.event?.[key])+'</b><span>'+esc(v.event?.[key+'d'])+'</span></button>').join('')+'</div>'+quote+'</section><section class="cm-card"><h2>'+esc(v.economy.name)+'</h2><p>'+esc(v.economy.text)+'</p><p>Benchmark rate '+Number(v.economy.rate).toFixed(2)+'% · '+Object.keys(v.territories).length+' markets · '+coreMultiBanks(v).length+' banks.</p><h3>Next operating estimate</h3><p>'+ (review.forecast?'Operating profit '+coreMultiMoney(review.forecast.profit??review.forecast.netProfit??review.forecast.operatingProfit):'Complete the required decisions to view the operating forecast.')+'</p><p class="cm-note">Estimates describe your current plan. Principal balances are not earnings.</p></section></div>'+coreMultiStandings(v)+'<section class="cm-card"><h2>'+ (v.resolutionId?'Latest monthly results':'Opening conditions')+'</h2>'+ (v.resolution?.length?'<ol class="cm-results">'+v.resolution.map(line=>'<li>'+esc(line)+'</li>').join(''):'<p>No month has resolved yet. Each human bank submits privately; AI banks act after the humans are ready.</p>')+'</section>';
}
function coreMultiMarkets(v){
 const keys=Object.keys(v.territories),selected=v.territories[coreMultiUi.market]?coreMultiUi.market:draft.focus,t=v.territories[selected],bankIds=v.bankIds||coreMultiBanks(v).map(bank=>bank.id),banks=new Map(coreMultiBanks(v).map(bank=>[bank.id,bank]));
 const positions=E.CORE_MAPS?.[v.coreMap||'continental']?.positions||{},links=E.CORE_MAPS?.[v.coreMap||'continental']?.links||[];
 const point=(key,i=0)=>v.territories[key].mapPosition||positions[key]||[10+(i%6)*16,12+Math.floor(i/6)*24];
 const roads=links.filter(([a,b])=>v.territories[a]&&v.territories[b]).map(([a,b])=>{const A=point(a),B=point(b);return '<line x1="'+A[0]+'" y1="'+A[1]+'" x2="'+B[0]+'" y2="'+B[1]+'"/>';}).join('');
 const map='<div class="cm-map-scroll" tabindex="0" aria-label="Market map"><div class="cm-map"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path class="cm-water" d="M46 0 L52 0 L56 34 L48 54 L55 77 L50 100 L44 100 L48 76 L41 54 L49 34 Z"/><g>'+roads+'</g></svg>'+keys.map((key,i)=>{const territory=v.territories[key],p=point(key,i),maximum=Math.max(...territory.shares),leaders=territory.shares.flatMap((share,index)=>share===maximum?[index]:[]),leader=leaders[0],tied=leaders.length>1,bank=banks.get(bankIds[leader]),mine=territory.shares[0]||0;return '<button type="button" class="cm-map-market" style="--x:'+p[0]+'%;--y:'+p[1]+'%;--bank-color:'+(tied?'#6f7f8f':coreMultiColor(bank?.color,leader))+'" data-cm-market="'+esc(key)+'" aria-pressed="'+(key===selected)+'" aria-label="'+esc(territory.name+', your influence '+mine.toFixed(1)+' percent, '+(territory.unlocked?'open':'locked'))+'"><b>'+esc(territory.name)+'</b><span>'+mine.toFixed(0)+'% influence'+(tied?' · shared lead':'')+'</span><small>'+Number(territory.branches?.[0]||0)+' of your offices</small></button>';}).join('')+'</div></div>';
 const distribution='<ul class="cm-influence">'+bankIds.map((id,i)=>{const bank=banks.get(id);return '<li>'+coreMultiBadge(bank||{name:'Bank'},i)+'<span>'+esc(bank?.name||id)+'</span><b>'+Number(t.shares[i]||0).toFixed(1)+'%</b><progress value="'+Number(t.shares[i]||0)+'" max="100">'+Number(t.shares[i]||0).toFixed(1)+'%</progress></li>';}).join('')+'</ul>';
 const projects=Object.entries(v.projects||{}).filter(([,definition])=>definition.target&&!definition.strategy&&!definition.legacy&&!definition.serviceOnly&&!definition.programOnly&&!definition.regionalOnly),planned=E.planInitiatives(draft);
 return '<label for="cmMarketSelect">Inspect market<select id="cmMarketSelect">'+keys.map(key=>'<option value="'+esc(key)+'" '+(key===selected?'selected':'')+'>'+esc(v.territories[key].name)+'</option>').join('')+'</select></label><p class="cm-map-hint cm-note">Swipe or scroll the map sideways to see every market, or choose a market above.</p><p class="cm-note">Select a market to inspect it. Your monthly focus is '+esc(v.territories[draft.focus]?.name||draft.focus)+'. Colored borders show the leading bank; influence is distinct from customer deposits.</p>'+map+'<section class="cm-card"><h2>'+esc(t.name)+'</h2><p>'+esc(t.mapRegion||t.specialty||'Local market')+' · market value '+Number(t.value||0)+'</p>'+distribution+'<button type="button" class="btn primary" data-cm-focus="'+esc(selected)+'" '+(!t.unlocked||t.exited?.[0]||selected===draft.focus?'disabled':'')+'>Use as monthly focus</button><h3>Local construction & acquisition</h3><p class="cm-note">These Core rules use monthly focus for local orders. Staging a local project here also changes the plan focus. Previously staged local projects follow that shared focus.</p><div class="cm-projects">'+projects.map(([key,definition])=>coreMultiProjectCard(v,key,definition,selected,planned)).join('')+'</div></section>';
}
function coreMultiProjectCard(v,key,definition,target,planned){
 let terms,status;try{terms=E.projectStartTerms(v,v.me,key,target);const candidate=coreMultiCopy(draft);candidate.focus=target;candidate.newProjects=planned.includes(key)?planned.filter(id=>id!==key):[...planned,key];candidate.newProject=candidate.newProjects[0]||null;status=E.projectPlanStatus(v.me,candidate,v);}catch(error){status={eligible:false,reason:error.message};}
 return '<article class="cm-project"><h4>'+esc(definition.name)+'</h4><p>'+esc(definition.desc)+'</p><p>'+coreMultiMoney(terms?.cost)+' upfront · '+esc(terms?.cycles??definition.cycles)+' work units · '+esc(definition.capacity||1.5)+' execution</p><button type="button" class="btn" data-cm-project="'+esc(key)+'" data-cm-project-market="'+esc(target)+'" '+(!planned.includes(key)&&!status?.eligible?'disabled':'')+'>'+ (planned.includes(key)?'Remove from plan':'Add to monthly plan')+'</button>'+(!status?.eligible?'<p class="cm-note">'+esc(status?.reason)+'</p>':'')+'</article>';
}
function coreMultiBank(v){
 const alloc=draft.allocation,used=Object.values(alloc).reduce((a,b)=>a+Number(b),0),pool=v.me.stats.staff-used;
 const policies=[['depositPolicy','Deposit pricing',v.depositPolicies],['lendingPolicy','Loan underwriting',v.lendingPolicies],['capitalPolicy','Capital reserve',v.capitalPolicies]].map(([path,title,table])=>'<fieldset><legend>'+title+'</legend><div class="cm-options">'+Object.entries(table).map(([key,p])=>'<button type="button" class="cm-choice" data-cm-policy="'+path+'" data-cm-value="'+key+'" aria-pressed="'+(draft[path]===key)+'"><b>'+esc(p.name)+'</b><span>'+esc(p.desc)+'</span></button>').join('')+'</div></fieldset>').join('');
 const products=Object.entries(v.productPortfolios||E.PRODUCT_PORTFOLIOS).map(([line,group])=>'<label>'+esc(group.name)+'<select data-cm-product="'+esc(line)+'">'+Object.entries(group.options).map(([key,p])=>'<option value="'+esc(key)+'" '+(draft.products[line]===key?'selected':'')+(E.researchProductBarred?.(v.me,line,key)?' disabled':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label>').join('');
 const opportunities=(v.opportunities||[]).map(o=>'<option value="'+esc(o.id)+'" '+(draft.opportunity===o.id?'selected':'')+'>'+esc(o.name||o.type)+' · '+esc(v.territories[o.market]?.name||o.market||'')+'</option>').join('');
 return (typeof coreMultiFinancialReport==='function'?coreMultiFinancialReport(v):'')+'<div class="cm-columns"><section class="cm-card"><h2>Allocate bankers</h2><p>'+v.me.stats.staff+' employees · '+(pool===0?'all assigned':pool+' unassigned')+'</p><div class="cm-staff">'+Object.entries(v.roles).map(([key,role])=>'<article><div><b>'+esc(role.name)+'</b><small>'+esc(role.desc)+'</small></div><button type="button" class="btn" data-cm-staff="'+key+'" data-cm-step="-1" '+(!alloc[key]?'disabled':'')+' aria-label="Reduce '+esc(role.name)+' allocation">−</button><output>'+Number(alloc[key]||0)+'</output><button type="button" class="btn" data-cm-staff="'+key+'" data-cm-step="1" '+(pool<=0?'disabled':'')+' aria-label="Increase '+esc(role.name)+' allocation">+</button></article>').join('')+'</div><label for="cmHires">New bankers next month</label><input id="cmHires" type="number" min="0" max="'+E.hireLimit(v.me)+'" step="1" value="'+Number(draft.hires||0)+'"><p class="cm-note">Recruitment pays signing costs now and adds recurring payroll from the next month. Current employees must all be allocated.</p></section><section class="cm-card"><h2>Customer offers</h2>'+products+'<label for="cmOpportunity">Optional customer opportunity</label><select id="cmOpportunity"><option value="">No pursuit</option>'+opportunities+'</select><p class="cm-note">Winning is conditional on staffing, market position and other banks. No pursuit is a valid monthly plan.</p></section></div><section class="cm-card"><h2>Operating policies</h2>'+policies+'</section>';
}
function coreMultiResearch(v){
 const branches=Object.entries(v.strategyBranches||{}),branch=branches.some(([key])=>key===coreMultiUi.branch)?coreMultiUi.branch:branches[0]?.[0],definition=v.strategyBranches[branch],funded=E.capabilitySpend(v.me,branch),tiers=v.capabilityTiers[branch]||E.CAPABILITY_TIERS[branch],level=E.strategyLevel(v.me,branch),models=v.strategySpecializations?.[branch]||E.researchModelTable(v.me)[branch]||{},permanent=v.me.specializations?.[branch];
 const projects=Object.entries(v.projects).filter(([,p])=>p.strategy&&!p.legacy),planned=E.planInitiatives(draft);
 return '<div class="cm-research"><nav aria-label="Research capabilities">'+branches.map(([key,d])=>'<button type="button" class="btn" data-cm-branch="'+esc(key)+'" aria-pressed="'+(key===branch)+'">'+esc(d.name)+'<small>Level '+E.strategyLevel(v.me,key)+' / '+(v.capabilityTiers[key]||E.CAPABILITY_TIERS[key]).length+'</small></button>').join('')+'</nav><section class="cm-card"><h2>'+esc(definition.name)+'</h2><p>'+esc(definition.promise||definition.desc||'')+'</p><p>Paid research '+coreMultiMoney(funded)+' · planned this month '+coreMultiMoney(Number(draft.investments[branch]||0))+'</p><ol class="cm-research-levels">'+definition.nodes.map((node,i)=>'<li class="'+(i<level?'cm-complete':'')+'"><b>'+esc(node.name)+'</b><span>'+coreMultiMoney(tiers[i])+' cumulative</span><p>'+esc(typeof strategyMilestoneDescription==='function'?strategyMilestoneDescription(v,branch,i):node.desc)+'</p></li>').join('')+'</ol><label for="cmResearchAmount">Research contribution this month</label><input id="cmResearchAmount" data-cm-research="'+esc(branch)+'" type="number" min="0" max="'+v.capabilityCap+'" step="1" value="'+Number(draft.investments[branch]||0)+'"><p class="cm-note">Enter zero to pause, or at least $1,000. Contributions are paid at settlement. Research benefits begin after completing a milestone.</p><label for="cmResearchModel">Permanent operating model</label><select id="cmResearchModel" data-cm-model="'+esc(branch)+'" '+(permanent?'disabled':'')+'><option value="">No model planned</option>'+Object.entries(models).map(([key,d])=>'<option value="'+esc(key)+'" '+((draft.specializations[branch]||permanent)===key?'selected':'')+'>'+esc(d.name)+'</option>').join('')+'</select><p class="cm-note">'+ (permanent?'This model has been permanently adopted.':'Requires this capability’s first funded milestone. Choosing a model becomes permanent after resolution.')+'</p></section></div><section class="cm-card"><h2>Implementation initiatives</h2><div class="cm-projects">'+projects.map(([key,d])=>coreMultiProjectCard(v,key,d,draft.focus,planned)).join('')+'</div></section>';
}
function coreMultiPlan(v,review){
 const banks=coreMultiBanks(v).filter(bank=>bank.id!==v.me.id&&!bank.eliminated),actions=Object.entries(E.COMPETITIVE_ACTIONS),planned=E.planInitiatives(draft);
 return '<div class="cm-columns"><section class="cm-card"><h2>Competition</h2><label for="cmRivalTarget">Opposing bank</label><select id="cmRivalTarget">'+banks.map(bank=>'<option value="'+esc(bank.id)+'" '+(draft.rivalId===bank.id?'selected':'')+'>'+esc(bank.name)+'</option>').join('')+'</select><label for="cmCompetitiveAction">Monthly competitive action</label><select id="cmCompetitiveAction">'+actions.map(([key,d])=>{let status;try{status=E.competitiveActionStatus(v.me,key);}catch(error){status={eligible:false};}return '<option value="'+key+'" '+(draft.competitiveAction===key?'selected':'')+(!status.eligible?'disabled':'')+'>'+esc(d.name)+'</option>';}).join('')+'</select><p>'+esc(E.COMPETITIVE_ACTIONS[draft.competitiveAction||'none']?.desc||'')+'</p><label class="cm-check"><input id="cmBoardCapital" type="checkbox" '+(draft.capitalAction?'checked':'')+(!v.me.capitalRequest?.eligible&&!draft.capitalAction?'disabled':'')+'> Request emergency board capital</label><p class="cm-note">'+esc(v.me.capitalRequest?.reason||'Board assistance carries permanent concessions and cannot accompany expansion.')+'</p></section><section class="cm-card"><h2>Monthly commitments</h2><dl class="cm-facts">'+[['Focus',v.territories[draft.focus]?.name],['Executive response',draft.decision?.toUpperCase()||'Unanswered'],['Research',coreMultiMoney(review.budget?.research)],['Recruitment',coreMultiMoney(review.budget?.recruiting)],['Initiatives',coreMultiMoney(review.budget?.projects)],['Competitive action',coreMultiMoney(review.budget?.action)],['Whole plan',coreMultiMoney(review.budget?.total)],['Remaining capacity to spend',coreMultiMoney(review.budget?.discretionaryRemaining??review.budget?.remaining)]].map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+esc(value??'Unavailable')+'</dd></div>').join('')+'</dl><h3>Planned initiatives</h3>'+ (planned.length?'<ul>'+planned.map(key=>'<li>'+esc(v.projects[key]?.name||key)+' <button type="button" class="btn" data-cm-project="'+esc(key)+'" data-cm-project-market="'+esc(draft.focus)+'">Remove</button></li>').join('')+'</ul>':'<p>No new initiative. Existing projects continue.</p>')+'<h3>Active projects</h3>'+ ((v.me.projects||[]).length?'<ul>'+v.me.projects.map(p=>'<li>'+esc(v.projects[p.key]?.name||p.key)+' · '+Number(p.progress)+' / '+Number(p.total)+' work units</li>').join('')+'</ul>':'<p>No project underway.</p>')+'</section></div><section class="cm-card"><h2>'+ (v.me.submitted?'Your plan is sealed':'Before Ready')+'</h2>'+ (review.errors.length?'<ul class="cm-errors">'+review.errors.map(error=>'<li>'+esc(error)+'</li>').join(''):'<p>Required choices are complete. A quiet month without optional spending is valid.</p>')+'<p class="cm-note">All active human banks must be ready. AI banks plan after the human plans are sealed. Recall is available while the month is still open.</p></section>';
}
function coreMultiSaves(v){return '<div class="cm-columns"><section class="cm-card"><h2>Save & resume</h2><p>'+ (coreMultiplayerOnlineActive()?'The room server holds the campaign. The host can export an authoritative backup containing every bank’s private books and orders. Reconnecting in this browser restores your own private seat.':'This browser saves the campaign after each submission. Export a backup before switching computers.')+'</p><button type="button" class="btn" id="cmExport" '+(coreMultiplayerOnlineActive()&&coreMultiOnline.seat!==0?'disabled':'')+'>Export campaign</button>'+(!coreMultiplayerOnlineActive()?'<button type="button" class="btn" id="cmImport">Import saved campaign</button>':'')+'<button type="button" class="btn danger" id="cmLeave">Return to setup</button></section><section class="cm-card"><h2>How to play</h2><p>Answer the executive decision, allocate every banker, then choose an open focus market. Pricing, products, research, construction and competitive actions all use the same monthly plan and budget.</p><p>Markets shows all participating banks. Only the current bank’s private staff, policies and orders appear. Local human turns use a covered handoff.</p>'+ (coreMultiplayerOnlineActive()?'<button type="button" class="btn" id="cmReconnectDownload">Download private reconnect key</button><p class="cm-note">The reconnect key opens your private bank. Keep it for yourself.</p><label for="cmInvite">Share this invitation</label><input id="cmInvite" readonly value="'+esc(coreMultiInvite())+'"><button type="button" class="btn" id="cmCopyInvite">Copy invitation</button><p class="cm-note">Room '+esc(coreMultiOnline.room)+' · each player joins with their own browser. An invitation contains no private seat key.</p>':'<p>AI banks and local human banks can share one campaign. The campaign ends according to its versioned multiplayer rules.</p>')+'</section></div>'+coreMultiStandings(v);}
function renderCoreMultiplayer(v=currentView()){
 if(!coreMultiplayerEnabled(v))return false;coreMultiEnsureDraft(v);coreMultiUi.revision++;coreMultiSetShell();
 const mount=$('#coreMultiplayerGame'),active=document.activeElement,retained=active?.id&&mount.contains?.(active)&&['INPUT','SELECT'].includes(active.tagName)?{id:active.id,value:active.value,checked:active.checked,start:active.selectionStart,end:active.selectionEnd}:null,review=coreMultiReview(v),token=coreMultiToken(v),locked=v.me.submitted||v.me.eliminated||v.gameOver||coreMultiOnline.writing,tabs=[['month','This month'],['markets','Markets'],['bank','Bank & people'],['research','Research'],['plan','Review plan'],['saves','Save & help']];
 if(v.gameOver)coreMultiUi.tab='month';
 const roster=coreMultiBanks(v).map((bank,i)=>'<li>'+coreMultiBadge(bank,i)+'<span>'+esc(bank.name)+'<small>'+ (bank.eliminated?'Eliminated':bank.submitted?'Ready':bank.isBot?'AI · waiting':'Human · planning')+'</small></span></li>').join('');
 let body=v.gameOver?'<section class="cm-card"><h2>Campaign complete</h2><p>'+esc(v.gameOver.reason||v.endReason||'The campaign has ended.')+'</p><p>'+esc(coreMultiBanks(v).find(bank=>bank.id===v.winnerId)?.name||'No sole winner')+'</p>'+coreMultiStandings(v)+'<button type="button" class="btn" id="cmExport">Export campaign</button><button type="button" class="btn" id="cmLeave">Return to setup</button></section>':coreMultiUi.tab==='markets'?coreMultiMarkets(v):coreMultiUi.tab==='bank'?coreMultiBank(v):coreMultiUi.tab==='research'?coreMultiResearch(v):coreMultiUi.tab==='plan'?coreMultiPlan(v,review):coreMultiUi.tab==='saves'?coreMultiSaves(v):coreMultiMonth(v,review);
 mount.innerHTML='<header class="cm-header">'+coreMultiBadge(v.me)+'<div><p class="cm-eyebrow">Core · '+esc(E.CORE_MAPS?.[v.coreMap]?.name||'Multiplayer')+' · month '+v.cycle+'</p><h1>'+esc(v.me.name)+'</h1><p>'+ (coreMultiplayerOnlineActive()?'Online room '+esc(coreMultiOnline.room):'Local campaign')+' · '+coreMultiBanks(v).length+' banks</p></div><dl class="cm-header-facts"><div><dt>Cash</dt><dd>'+coreMultiMoney(v.me.stats.cash)+'</dd></div><div><dt>Available after plan</dt><dd>'+coreMultiMoney(review.budget?.discretionaryRemaining??review.budget?.remaining)+'</dd></div><div><dt>Capital</dt><dd>'+Number(v.me.capitalRatio).toFixed(1)+'%</dd></div></dl></header><ul class="cm-roster" aria-label="Participating banks">'+roster+'</ul><nav class="cm-tabs" aria-label="Core multiplayer workspaces">'+tabs.map(([key,label])=>'<button type="button" class="btn" data-cm-tab="'+key+'" aria-current="'+(key===coreMultiUi.tab?'page':'false')+'">'+label+'</button>').join('')+'</nav><p class="cm-status '+(coreMultiUi.error||coreMultiOnline.error?'cm-error':'')+'" role="status" aria-live="polite">'+esc(coreMultiUi.error||coreMultiOnline.error||coreMultiUi.notice||coreMultiOnline.notice||'Your monthly plan is private until resolution.')+'</p><div class="cm-content">'+body+'</div>'+(!v.gameOver?'<footer class="cm-ready"><p>'+ (v.me.eliminated?'Your bank has been eliminated. Public results remain available.':v.me.submitted?'Your plan is sealed. Waiting for the remaining active human banks.':review.errors[0]||'Required choices complete. Review your plan, then Ready.')+'</p><button type="button" class="btn primary" id="cmReady" '+(locked||review.errors.length?'disabled':'')+'>Ready for month '+v.cycle+'</button><button type="button" class="btn" id="cmRecall" '+(!v.me.submitted||v.me.eliminated||coreMultiOnline.writing?'disabled':'')+'>Recall plan</button>'+(!coreMultiplayerOnlineActive()&&game?.players.filter(p=>!p.isBot&&!p.eliminated).length>1?'<button type="button" class="btn" id="cmHandoff">Cover & pass to another bank</button>':'')+'</footer>':'');
 mount.querySelectorAll('[data-cm-decision],[data-cm-policy],[data-cm-product],[data-cm-staff],[data-cm-project],#cmHires,#cmResearchAmount,#cmResearchModel,#cmOpportunity,#cmRivalTarget,#cmCompetitiveAction,#cmBoardCapital').forEach(control=>{if(locked)control.disabled=true;});
 coreMultiBind(mount,token);if(v.me.eliminated&&!v.gameOver&&!coreMultiBanks(v).some(bank=>!bank.isBot&&!bank.eliminated)&&(!coreMultiplayerOnlineActive()||coreMultiOnline.seat===0)){const actions=mount.querySelector('.cm-ready');actions?.insertAdjacentHTML('beforeend','<button type="button" class="btn primary" id="cmObserve">Observe next month</button>');$('#cmObserve')?.addEventListener('click',()=>{if(coreMultiCurrent(token,false))coreMultiAdvance();});}if(retained&&!locked){const input=$('#'+retained.id);if(input&&!input.disabled&&mount.contains?.(input)){input.value=retained.value;input.checked=retained.checked;input.focus?.({preventScroll:true});if(Number.isInteger(retained.start))try{input.setSelectionRange(retained.start,retained.end);}catch(error){}}}return true;
}
function coreMultiBind(mount,token){
 mount.querySelectorAll('[data-cm-tab]').forEach(button=>button.addEventListener('click',()=>{if(!coreMultiCurrent(token,false))return;coreMultiUi.tab=button.dataset.cmTab;renderCoreMultiplayer(currentView());$('#coreMultiplayerGame h1')?.focus?.({preventScroll:true});}));
 $('#cmMarketSelect')?.addEventListener('change',event=>{if(!coreMultiCurrent(token,false))return;coreMultiUi.market=event.target.value;renderCoreMultiplayer(currentView());});
 mount.querySelectorAll('[data-cm-market]').forEach(button=>button.addEventListener('click',()=>{if(!coreMultiCurrent(token,false))return;coreMultiUi.market=button.dataset.cmMarket;renderCoreMultiplayer(currentView());}));
 mount.querySelectorAll('[data-cm-branch]').forEach(button=>button.addEventListener('click',()=>{if(!coreMultiCurrent(token,false))return;coreMultiUi.branch=button.dataset.cmBranch;renderCoreMultiplayer(currentView());}));
 mount.querySelectorAll('[data-cm-decision]').forEach(button=>button.addEventListener('click',()=>coreMultiUpdate(token,next=>{next.decision=button.dataset.cmDecision;})));
 mount.querySelectorAll('[data-cm-policy]').forEach(button=>button.addEventListener('click',()=>coreMultiUpdate(token,next=>{next[button.dataset.cmPolicy]=button.dataset.cmValue;})));
 mount.querySelectorAll('[data-cm-product]').forEach(input=>input.addEventListener('change',()=>coreMultiUpdate(token,next=>{next.products[input.dataset.cmProduct]=input.value;})));
 mount.querySelectorAll('[data-cm-focus]').forEach(button=>button.addEventListener('click',()=>coreMultiUpdate(token,next=>{next.focus=button.dataset.cmFocus;})));
 mount.querySelectorAll('[data-cm-staff]').forEach(button=>button.addEventListener('click',()=>coreMultiUpdate(token,(next,v)=>{const role=button.dataset.cmStaff,step=Number(button.dataset.cmStep),total=Object.values(next.allocation).reduce((a,b)=>a+b,0);if(step<0&&next.allocation[role]>0)next.allocation[role]--;if(step>0&&total<v.me.stats.staff)next.allocation[role]++;})));
 mount.querySelectorAll('[data-cm-project]').forEach(button=>button.addEventListener('click',()=>coreMultiUpdate(token,(next,v)=>{const key=button.dataset.cmProject,chosen=E.planInitiatives(next),remove=chosen.includes(key);next.newProjects=remove?chosen.filter(id=>id!==key):[...chosen,key];next.newProject=next.newProjects[0]||null;if(!remove&&v.projects[key]?.target)next.focus=button.dataset.cmProjectMarket;if(!remove&&['branch','acquisition'].includes(v.projects[key]?.kind))next.capitalAction=false;const status=E.projectPlanStatus(v.me,next,v);if(!remove&&!status.eligible)throw Error(status.reason);})));
 const change=(id,edit)=>$('#'+id)?.addEventListener('change',event=>coreMultiUpdate(token,(next,v)=>edit(next,event.target,v)));
 change('cmHires',(next,input,v)=>{const n=Number(input.value);if(!input.value.trim()||!Number.isSafeInteger(n)||n<0||n>E.hireLimit(v.me))throw Error('Enter a whole recruitment count within the monthly limit.');next.hires=n;});
 change('cmResearchAmount',(next,input,v)=>{const n=Number(input.value),branch=input.dataset.cmResearch;if(!input.value.trim()||!Number.isSafeInteger(n)||n<0||n>v.capabilityCap||n>0&&n<1000)throw Error('Research funding must be zero or at least $1,000 in whole dollars, within the monthly cap.');next.investments[branch]=n;});
 change('cmResearchModel',(next,input)=>{if(input.value)next.specializations[input.dataset.cmModel]=input.value;else delete next.specializations[input.dataset.cmModel];});
 change('cmOpportunity',(next,input)=>{next.opportunity=input.value||null;});change('cmRivalTarget',(next,input)=>{next.rivalId=input.value;});change('cmCompetitiveAction',(next,input)=>{next.competitiveAction=input.value;});change('cmBoardCapital',(next,input)=>{next.capitalAction=input.checked;});
 $('#cmReady')?.addEventListener('click',()=>{if(coreMultiCurrent(token))submitCoreMultiplayer();});$('#cmRecall')?.addEventListener('click',()=>{if(coreMultiCurrent(token,false))recallCoreMultiplayer();});
 $('#cmHandoff')?.addEventListener('click',()=>{if(coreMultiCurrent(token,false))coreMultiHandoff();});$('#cmExport')?.addEventListener('click',()=>{if(coreMultiCurrent(token,false))coreMultiExport();});$('#cmImport')?.addEventListener('click',()=>{if(coreMultiCurrent(token,false))$('#importFile').click();});$('#cmLeave')?.addEventListener('click',()=>{if(coreMultiCurrent(token,false))leaveGame();});
 $('#cmReconnectDownload')?.addEventListener('click',()=>{if(coreMultiCurrent(token,false))coreMultiExportKey();});
 $('#cmCopyInvite')?.addEventListener('click',async()=>{if(!coreMultiCurrent(token,false))return;try{await navigator.clipboard.writeText(coreMultiInvite());coreMultiUi.notice='Invitation copied.';}catch(error){coreMultiUi.notice='Select and copy the invitation above.';}renderCoreMultiplayer(currentView());});
}
function coreMultiHandoff(nextSeat){
 if(!game)return false;const humans=game.players.map((bank,index)=>({bank,index})).filter(row=>!row.bank.isBot&&!row.bank.eliminated);if(humans.length<2)return false;
 const next=nextSeat??humans.find(row=>row.index>seat)?.index??humans[0].index;if(next===seat)return false;
 if(draft&&draftOwner===game.players[seat].id&&!game.players[seat].submitted)coreMultiLocalDrafts.plans.set(draftOwner,coreMultiCopy(draft));
 showPrivacy(next,'PASS TO '+game.players[next].name.toUpperCase(),'Only '+game.players[next].name+' should uncover this bank’s private plan.');return true;
}
async function submitCoreMultiplayer(){
 const v=currentView(),review=coreMultiReview(v);if(review.errors.length){coreMultiUi.error=review.errors[0];renderCoreMultiplayer(v);return false;}
 try{
  if(coreMultiplayerOnlineActive()){await coreMultiRoomRequest('plan',{commandId:coreMultiCommandId(),cycle:v.cycle,resolutionId:v.resolutionId,plan:coreMultiCopy(draft)});return true;}
  const previous=v.cycle;E.submit(game,seat,coreMultiCopy(draft));saveLocal();
  const humans=game.players.map((bank,index)=>({bank,index})).filter(row=>!row.bank.isBot&&!row.bank.eliminated),unsubmitted=humans.find(row=>!row.bank.submitted);
  if(game.cycle!==previous||game.gameOver){const first=humans[0]?.index??seat;if(first!==seat&&humans.length>1){showPrivacy(first,'MONTH '+previous+' RESOLVED','Pass to '+game.players[first].name+' to review the results.');return true;}draft=null;}
  else if(unsubmitted&&unsubmitted.index!==seat){coreMultiHandoff(unsubmitted.index);return true;}
  renderCoreMultiplayer(currentView());return true;
 }catch(error){coreMultiUi.error=error.message;renderCoreMultiplayer(currentView());return false;}
}
async function recallCoreMultiplayer(){try{const v=currentView();if(coreMultiplayerOnlineActive())await coreMultiRoomRequest('recall',{commandId:coreMultiCommandId(),cycle:v.cycle,resolutionId:v.resolutionId});else{E.recallCoreMultiplayer(game,seat);saveLocal();draft=null;renderCoreMultiplayer(currentView());}}catch(error){coreMultiUi.error=error.message;renderCoreMultiplayer(currentView());}}
function resumeCoreMultiplayer(restored){
 if(restored?.coreMultiplayerVersion!==1)return false;coreMultiplayerDisconnect();resetLink();game=restored;view=null;p2pRole='';mode='hotseat';seat=game.players.findIndex(bank=>!bank.isBot&&!bank.eliminated&&!bank.submitted);if(seat<0)seat=game.players.findIndex(bank=>!bank.isBot);if(seat<0)seat=0;draft=null;draftOwner='';lastCycle=0;lastResolutionId=game.resolutionId||0;saveLocal();show('#gameScreen');
 if(game.players.filter(bank=>!bank.isBot&&!bank.eliminated).length>1)showPrivacy(seat,'PASS TO '+game.players[seat].name.toUpperCase(),'Uncover the campaign only when this bank’s player is ready.');else renderCoreMultiplayer(currentView());return true;
}
function renderCoreMultiplayerSetup(){
 const mount=$('#coreMultiplayerSetup');if(!mount)return;
 mount.innerHTML='<details class="cm-setup" open><summary>Core · larger map & 2–4 banks</summary><p>Play 24 fictional markets with any mix of human and AI opponents. Human banks plan privately on one computer or join an online room.</p><div class="cm-setup-fields"><label for="cmBankCount">Banks<select id="cmBankCount">'+[2,3,4].map(n=>'<option value="'+n+'" '+(n===coreMultiSetup.count?'selected':'')+'>'+n+' banks</option>').join('')+'</select></label><label for="cmMapChoice">Map<select id="cmMapChoice"><option value="continental" '+(coreMultiSetup.map==='continental'?'selected':'')+'>Continental · 24 markets</option><option value="national" '+(coreMultiSetup.map==='national'?'selected':'')+'>National · 12 markets</option></select></label><label for="cmScenarioChoice">Economy<select id="cmScenarioChoice">'+Object.entries(E.SCENARIOS).map(([key,d])=>'<option value="'+key+'" '+(key===coreMultiSetup.scenario?'selected':'')+'>'+esc(d.name||d)+'</option>').join('')+'</select></label><label for="cmDifficultyChoice">Local AI difficulty<select id="cmDifficultyChoice">'+[['analyst','Junior analysts'],['vp','Regional VPs'],['chairman','Chairman’s office']].map(([key,label])=>'<option value="'+key+'" '+(key===coreMultiSetup.difficulty?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label for="cmSeed">Seed (optional)<input id="cmSeed" maxlength="100" value="'+esc(coreMultiSetup.seed)+'" placeholder="A repeatable campaign seed"></label></div><div class="cm-setup-roster">'+coreMultiSetup.players.slice(0,coreMultiSetup.count).map((bank,i)=>'<fieldset><legend>Bank '+(i+1)+'</legend><label for="cmBankName'+i+'">Name<input id="cmBankName'+i+'" maxlength="36" value="'+esc(bank.name)+'"></label><label for="cmBankType'+i+'">Player<select id="cmBankType'+i+'" '+(!i?'disabled':'')+'><option value="human" '+(!bank.isBot?'selected':'')+'>Human</option><option value="ai" '+(bank.isBot?'selected':'')+'>AI</option></select></label><label for="cmBankColor'+i+'">Color<input id="cmBankColor'+i+'" type="color" value="'+coreMultiColor(bank.color,i)+'"></label></fieldset>').join('')+'</div><button type="button" class="btn primary" id="cmStartLocal">Start local campaign</button><div class="cm-online-setup"><h3>Online room</h3><p>Use a game server reachable by every player. Share its server address and room code. Each person joins their own private bank.</p><label for="cmServerUrl">Game server address<input id="cmServerUrl" type="url" value="'+esc(coreMultiDefaultServer())+'" placeholder="https://your-game-server.example"></label><label for="cmRoomCode">Room code<input id="cmRoomCode" maxlength="16" autocomplete="off" value="'+esc(coreMultiInitialRoom())+'" placeholder="Room code from the host"></label><div class="cm-actions"><button type="button" class="btn" id="cmCreateRoom">Create online room</button><button type="button" class="btn" id="cmJoinRoom">Join room as Bank 1 name</button><button type="button" class="btn" id="cmReconnectRoom">Reconnect remembered bank</button><label class="btn" for="cmReconnectKeyFile">Reconnect with private key</label><input id="cmReconnectKeyFile" type="file" accept=".json,application/json" hidden><label class="btn" for="cmRoomSaveFile">Create room from campaign save</label><input id="cmRoomSaveFile" type="file" accept=".json,application/json" hidden></div><label class="cm-check"><input id="cmRememberSeat" type="checkbox" checked> Remember this private bank on this device</label><p class="cm-note">Your private seat key stays in this browser. You can also download a reconnect key after joining.</p><p class="cm-note">Room creation uses the roster above. Human slots are claimed by joining; AI slots are filled by the server. Online uses the bank count, player types, map, economy, seed and Bank 1 name. Other names, colors and AI difficulty above apply to local play.</p></div><p id="cmSetupStatus" class="cm-status" role="status"></p></details>';
 $('#cmBankCount').addEventListener('change',()=>{try{coreMultiReadSetup();coreMultiSetup.count=Number($('#cmBankCount').value);renderCoreMultiplayerSetup();}catch(error){$('#cmSetupStatus').textContent=error.message;}});
 $('#cmStartLocal').addEventListener('click',startCoreMultiplayer);$('#cmCreateRoom').addEventListener('click',()=>coreMultiConnect('create'));$('#cmJoinRoom').addEventListener('click',()=>coreMultiConnect('join'));$('#cmReconnectRoom').addEventListener('click',coreMultiReconnect);$('#cmReconnectKeyFile').addEventListener('change',event=>coreMultiImportKey(event.target.files[0]));$('#cmRoomSaveFile').addEventListener('change',event=>coreMultiCreateFromSave(event.target.files[0]));
}
function coreMultiReadSetup(){
 const oldCount=coreMultiSetup.count;for(let i=0;i<oldCount;i++){const name=$('#cmBankName'+i).value.trim().replace(/\s+/g,' ');if(!name)throw Error('Give every bank a name.');coreMultiSetup.players[i]={name,isBot:i>0&&$('#cmBankType'+i).value==='ai',color:coreMultiColor($('#cmBankColor'+i).value,i)};}
 coreMultiSetup.map=$('#cmMapChoice').value;coreMultiSetup.scenario=$('#cmScenarioChoice').value;coreMultiSetup.difficulty=$('#cmDifficultyChoice').value;coreMultiSetup.seed=$('#cmSeed').value.trim();return coreMultiCopy(coreMultiSetup);
}
function startCoreMultiplayer(){
 try{const setup=coreMultiReadSetup(),options=E.previewCampaignEdition({},'core',{currentReporting:true,currentEconomics:true,currentResearch:true,currentLending:true,currentMonetaryPolicy:true}).options;
  const created=E.createGame({...options,coreMultiplayerVersion:1,coreMap:setup.map,players:setup.players.slice(0,setup.count),scope:'national',mode:'hotseat',scenario:setup.scenario,difficulty:setup.difficulty,...(setup.seed?{seed:setup.seed}:{})});resumeCoreMultiplayer(created);
 }catch(error){$('#cmSetupStatus').textContent=error.message;}
}
function coreMultiInitialRoom(){try{return new URL(location.href).searchParams.get('coreRoom')||'';}catch(error){return '';}}
function coreMultiDefaultServer(){try{return new URL(location.href).searchParams.get('coreServer')||(location.protocol==='http:'||location.protocol==='https:'?location.origin:'');}catch(error){return '';}}
function coreMultiServer(raw){
 const url=new URL(String(raw).trim());if(url.username||url.password||url.search||url.hash)throw Error('Use a server address without credentials, query strings or fragments.');
 const octets=url.hostname.split('.'),ipv4=octets.length===4&&octets.every(part=>/^\d+$/.test(part)&&Number(part)<=255),numbers=octets.map(Number);
 const local=url.hostname==='localhost'||url.hostname==='127.0.0.1'||url.hostname==='[::1]'||ipv4&&(numbers[0]===10||numbers[0]===192&&numbers[1]===168||numbers[0]===172&&numbers[1]>=16&&numbers[1]<=31);
 if(url.protocol!=='https:'&&!(url.protocol==='http:'&&local))throw Error('Use HTTPS for an internet server, or HTTP for a local-network server.');return url.href.replace(/\/$/,'');
}
function coreMultiCommandId(){return 'cm-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));}
function coreMultiPersist(){
 const record=JSON.stringify({base:coreMultiOnline.base,room:coreMultiOnline.room,seat:coreMultiOnline.seat,token:coreMultiOnline.token});
 try{sessionStorage.setItem('branchWarsCoreRoom',record);if(coreMultiRemember)localStorage.setItem('branchWarsCoreRoom',record);else localStorage.removeItem('branchWarsCoreRoom');}
 catch(error){coreMultiOnline.notice='Download a private reconnect key before closing this tab; browser reconnect storage is unavailable.';}
}
function coreMultiSavedSeat(){return JSON.parse(sessionStorage.getItem('branchWarsCoreRoom')||localStorage.getItem('branchWarsCoreRoom')||'null');}
function coreMultiDownload(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
function coreMultiExportKey(){if(!coreMultiplayerOnlineActive())return;const session=coreMultiOnline;coreMultiDownload({format:'branch-wars-private-seat',version:1,base:session.base,room:session.room,seat:session.seat,token:session.token},'Branch_Wars_Private_Seat_'+session.room+'.json');}
function coreMultiImportKey(file){
 if(!file)return;const generation=coreMultiOnline.generation,reader=new FileReader();reader.onload=async()=>{if(coreMultiOnline.generation!==generation)return;try{const saved=JSON.parse(reader.result);if(saved.format!=='branch-wars-private-seat'||saved.version!==1)throw Error('Choose a Branch Wars private reconnect key.');await coreMultiReconnect(saved);}catch(error){$('#cmSetupStatus').textContent=error.message;}};reader.onerror=()=>{$('#cmSetupStatus').textContent='The reconnect key could not be read.';};reader.readAsText(file);
}
function coreMultiCreateFromSave(file){
 if(!file)return;const generation=coreMultiOnline.generation,reader=new FileReader();reader.onload=async()=>{if(coreMultiOnline.generation!==generation)return;try{const restored=migrateGame(JSON.parse(reader.result));if(restored.coreMultiplayerVersion!==1)throw Error('Choose a Core multiplayer campaign save.');await coreMultiConnect('create',restored);}catch(error){$('#cmSetupStatus').textContent=error.message;}};reader.onerror=()=>{$('#cmSetupStatus').textContent='The campaign save could not be read.';};reader.readAsText(file);
}
function coreMultiplayerDisconnect(){clearTimeout(coreMultiOnline.timer);coreMultiOnline={base:'',room:'',seat:null,token:'',lobby:null,busy:false,timer:null,generation:coreMultiOnline.generation+1,error:'',notice:'',connected:false};}
async function coreMultiFetch(url,body,token=''){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
 try{const response=await fetch(url,{method:body===undefined?'GET':'POST',headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(token?{Authorization:'Bearer '+token}:{})},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal,credentials:'omit',redirect:'error'});let result;try{result=await response.json();}catch(error){throw Error('The server did not return a game response. Check its address.');}if(!response.ok)throw Error(result.error||'Game server request failed ('+response.status+').');return result;}finally{clearTimeout(timer);}
}
function coreMultiAdopt(result){
 const changed=!!coreMultiOnline.error||JSON.stringify(coreMultiOnline.lobby)!==JSON.stringify(result.lobby||coreMultiOnline.lobby)||JSON.stringify(view)!==JSON.stringify(result.state||null);
 coreMultiOnline.lobby=result.lobby||coreMultiOnline.lobby;coreMultiOnline.seat=result.seat??coreMultiOnline.seat;coreMultiOnline.error='';coreMultiOnline.connected=true;game=null;view=result.state||null;seat=coreMultiOnline.seat;p2pRole='';mode='lan';
 if(!changed&&$('#coreMultiplayerGame')?.hidden===false)return;
 if(view)renderCoreMultiplayer(view);else renderCoreMultiplayerOnline();
}
async function coreMultiConnect(kind,restoredGame){
 if(coreMultiConnecting)return;coreMultiConnecting=true;const status=$('#cmSetupStatus'),generation=coreMultiOnline.generation;
 for(const id of ['cmCreateRoom','cmJoinRoom','cmReconnectRoom','cmStartLocal'])if($('#'+id))$('#'+id).disabled=true;
 try{const setup=coreMultiReadSetup(),base=coreMultiServer($('#cmServerUrl').value),room=$('#cmRoomCode').value.trim().toUpperCase();coreMultiRemember=$('#cmRememberSeat')?.checked!==false;if(kind==='join'&&!/^[A-Z0-9_-]{4,16}$/.test(room))throw Error('Enter the host’s room code.');status.textContent=kind==='create'?'Creating room…':'Joining room…';
  const body=kind==='create'?{bankName:setup.players[0].name,players:setup.count,aiSeats:setup.players.slice(0,setup.count).flatMap((bank,i)=>bank.isBot?[i]:[]),coreMap:setup.map,scenario:setup.scenario,...(setup.seed?{seed:setup.seed}:{})}:{bankName:setup.players[0].name};
  if(restoredGame)body.game=restoredGame;
  const result=await coreMultiFetch(base+'/api/multiplayer/rooms'+(kind==='join'?'/'+encodeURIComponent(room)+'/join':''),body);if(typeof result.token!=='string'||!result.token)throw Error('The server did not issue a private seat key.');
  if(coreMultiOnline.generation!==generation){coreMultiDownload({format:'branch-wars-private-seat',version:1,base,room:result.room,seat:result.seat,token:result.token},'Branch_Wars_Private_Seat_'+result.room+'.json');return;}
  coreMultiplayerDisconnect();resetLink();coreMultiOnline={...coreMultiOnline,base,room:result.room,seat:result.seat,token:result.token};draft=null;draftOwner='';lastCycle=0;coreMultiPersist();coreMultiAdopt(result);coreMultiPoll();
 }catch(error){status.textContent=error.name==='AbortError'?'The server did not respond in time. Check its address and retry.':error.message;}
 finally{coreMultiConnecting=false;for(const id of ['cmCreateRoom','cmJoinRoom','cmReconnectRoom','cmStartLocal'])if($('#'+id))$('#'+id).disabled=false;}
}
async function coreMultiReconnect(supplied){
 if(coreMultiConnecting)return;coreMultiConnecting=true;const status=$('#cmSetupStatus');
 try{const saved=supplied?.token?supplied:coreMultiSavedSeat();if(typeof saved?.token!=='string'||!saved.token||!/^[A-Z0-9_-]{4,16}$/.test(saved.room)||!Number.isInteger(saved.seat)||saved.seat<0||saved.seat>3)throw Error('No usable private room seat is saved on this device. Import its reconnect key.');coreMultiplayerDisconnect();resetLink();coreMultiOnline={...coreMultiOnline,base:coreMultiServer(saved.base),room:saved.room,seat:saved.seat,token:saved.token};draft=null;draftOwner='';lastCycle=0;await coreMultiRoomRequest('');coreMultiRemember=$('#cmRememberSeat')?.checked!==false;coreMultiPersist();coreMultiPoll();}catch(error){coreMultiplayerDisconnect();status.textContent=error.message;}finally{coreMultiConnecting=false;}
}
async function coreMultiRoomRequest(action='',body){
 const session=coreMultiOnline,generation=session.generation,writing=body!==undefined;if(!session.token)throw Error('Join a room first.');
 if(session.busy){if(!writing||session.writing)throw Error('A room request is already in progress.');session.writing=true;try{await session.pending;}catch(error){}if(coreMultiOnline!==session||session.generation!==generation)return null;}
 session.busy=true;session.writing=writing;
 if(writing)for(const id of ['cmReady','cmRecall','cmLobbyReady','cmLobbyStart'])if($('#'+id))$('#'+id).disabled=true;
 try{session.pending=coreMultiFetch(session.base+'/api/multiplayer/rooms/'+encodeURIComponent(session.room)+(action?'/'+action:''),body,session.token);const result=await session.pending;if(coreMultiOnline!==session||coreMultiOnline.generation!==generation)return null;session.busy=false;session.writing=false;coreMultiAdopt(result);return result;}catch(error){if(coreMultiOnline===session){session.busy=false;session.writing=false;session.connected=false;session.error=error.name==='AbortError'?'Connection timed out. Your last confirmed plan is retained; polling will retry.':error.message;if(view)renderCoreMultiplayer(view);else renderCoreMultiplayerOnline();}throw error;}finally{if(coreMultiOnline===session){session.busy=false;session.writing=false;}}
}
function coreMultiPoll(){
 const session=coreMultiOnline;clearTimeout(session.timer);session.timer=setTimeout(async()=>{if(coreMultiOnline!==session||!session.token)return;try{if(!session.busy)await coreMultiRoomRequest('');}catch(error){}if(coreMultiOnline===session)coreMultiPoll();},2500);
}
function coreMultiInvite(){try{const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('coreRoom',coreMultiOnline.room);url.searchParams.set('coreServer',coreMultiOnline.base);return url.href;}catch(error){return coreMultiOnline.base+' · room '+coreMultiOnline.room;}}
function renderCoreMultiplayerOnline(){
 if(!coreMultiplayerOnlineActive())return false;if(view)return renderCoreMultiplayer(view);coreMultiSetShell();const session=coreMultiOnline,lobby=session.lobby,revision=lobby?.revision,mount=$('#coreMultiplayerGame');
 const nameInput=document.activeElement?.id==='cmOnlineName'?document.activeElement.value:null;
 mount.innerHTML='<header class="cm-header"><div><p class="cm-eyebrow">Online Core campaign</p><h1>Room '+esc(session.room)+'</h1><p>'+esc(E.CORE_MAPS?.[lobby?.settings?.coreMap]?.name||'Core multiplayer')+' · '+Number(lobby?.settings?.players||0)+' banks</p></div></header><section class="cm-card"><h2>Room roster</h2><p>Each human joins their own bank, then confirms ready. The host starts when everyone is present and ready. The server host is trusted with the full campaign; host backups contain every bank’s private books and orders.</p><ul class="cm-lobby-roster">'+(lobby?.players||[]).map(bank=>'<li><b>'+esc(bank.name||'Open bank slot')+'</b><span>'+ (bank.isBot?'AI · ready':!bank.claimed?'Waiting for player':bank.ready?'Human · ready':'Human · not ready')+(bank.seat===session.seat?' · You':'')+(bank.host?' · Host':'')+'</span></li>').join('')+'</ul><label for="cmOnlineName">Your bank name<input id="cmOnlineName" maxlength="36" value="'+esc(lobby?.players?.find(bank=>bank.seat===session.seat)?.name||'')+'"></label><button type="button" class="btn" id="cmUpdateIdentity" '+(session.busy?'disabled':'')+'>Save name</button><div class="cm-actions"><button type="button" class="btn primary" id="cmLobbyReady" '+(session.busy?'disabled':'')+'>'+ (lobby?.players?.find(bank=>bank.seat===session.seat)?.ready?'Not ready':'Confirm ready')+'</button>'+ (session.seat===0?'<button type="button" class="btn primary" id="cmLobbyStart" '+(session.busy||!lobby?.players.every(bank=>bank.isBot||bank.claimed&&bank.ready)?'disabled':'')+'>Start campaign</button>':'')+'<button type="button" class="btn" id="cmLobbyRefresh">Refresh room</button><button type="button" class="btn danger" id="cmLeave">Return to setup</button></div><p class="cm-status '+(session.error?'cm-error':'')+'" role="status">'+esc(session.error||session.notice||'Waiting in lobby.')+'</p></section><section class="cm-card"><h2>Invite your opponents</h2><button type="button" class="btn" id="cmReconnectDownload">Download private reconnect key</button><p class="cm-note">Keep this key for yourself; it opens your private bank after closing this tab.</p><label for="cmInvite">Invitation<input id="cmInvite" readonly value="'+esc(coreMultiInvite())+'"></label><p>Server '+esc(session.base)+' · room '+esc(session.room)+'. No private seat key is included.</p></section>';
 const fresh=()=>coreMultiOnline===session&&session.lobby?.revision===revision;
 $('#cmLobbyReady')?.addEventListener('click',async()=>{if(!fresh())return;try{await coreMultiRoomRequest('ready',{revision,ready:!lobby.players.find(bank=>bank.seat===session.seat)?.ready});}catch(error){}});
 $('#cmUpdateIdentity')?.addEventListener('click',async()=>{if(!fresh())return;try{await coreMultiRoomRequest('identity',{revision,bankName:$('#cmOnlineName').value.trim()});}catch(error){}});
 $('#cmLobbyStart')?.addEventListener('click',async()=>{if(!fresh())return;try{await coreMultiRoomRequest('start',{revision});}catch(error){}});
 $('#cmReconnectDownload')?.addEventListener('click',()=>{if(coreMultiOnline===session)coreMultiExportKey();});
 $('#cmLobbyRefresh')?.addEventListener('click',async()=>{if(!fresh())return;try{await coreMultiRoomRequest('');}catch(error){}});$('#cmLeave')?.addEventListener('click',leaveGame);if(nameInput!==null){$('#cmOnlineName').value=nameInput;$('#cmOnlineName').focus?.({preventScroll:true});}return true;
}
async function coreMultiExport(){
 if(!coreMultiplayerOnlineActive()){exportSave();return;}
 try{if(coreMultiOnline.seat!==0)throw Error('Only the room host can export the authoritative campaign.');const session=coreMultiOnline,result=await coreMultiFetch(session.base+'/api/multiplayer/rooms/'+encodeURIComponent(session.room)+'/export',undefined,session.token);if(coreMultiOnline!==session)return;const data=result.game||result,blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='Branch_Wars_Core_Room_'+session.room+'_Save.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}catch(error){coreMultiUi.error=error.message;renderCoreMultiplayer(currentView());}
}
async function coreMultiAdvance(){
 try{const v=currentView();if(coreMultiBanks(v).some(bank=>!bank.isBot&&!bank.eliminated))throw Error('Active human banks must submit their own plans.');if(coreMultiplayerOnlineActive())await coreMultiRoomRequest('advance',{commandId:coreMultiCommandId(),cycle:v.cycle,resolutionId:v.resolutionId});else{E.advanceCoreMultiplayerBots(game);draft=null;saveLocal();renderCoreMultiplayer(currentView());}}catch(error){coreMultiUi.error=error.message;renderCoreMultiplayer(currentView());}
}
